<?php if (!($data['preview'] ?? false)) { require __DIR__ . '/live/deliveries.php'; return; } ?>
<?php use App\UI\UI as U; $s=$data['sample']; $ready=array_values(array_filter($s['orders'],fn($o)=>$o[7]==='delivery' && $o[5]==='Ready')); $selected=array_values(array_filter($ready,fn($o)=>$o[2]==='Guintas')); $selectedLoad=array_sum(array_column($selected,3)); $queryTab=$_GET['tab']??'active'; $tab=is_string($queryTab) && in_array($queryTab,['active','ready','completed'],true)?$queryTab:'active'; ?>
<?= U::heading('Deliveries','Build and monitor your station’s delivery trips.',U::btn('Build a trip','/station-admin/deliveries#dispatch','primary','plus')) ?>
<?php $active = count(array_filter($s['trips'], fn($t) => $t['status'] !== 'Completed')); $done = count($s['trips']) - $active; $free = count(array_filter($s['drivers'], fn($d) => $d[3] === 'Available')); ?>
<div class="mb-5 grid grid-cols-2 gap-3 xl:grid-cols-4"><?= U::stat('Active trips',(string)$active,'truck','blue','Out on the road now','Live') ?><?= U::stat('Ready to dispatch',(string)count($ready),'check','green','Delivery orders waiting','Ready') ?><?= U::stat('Available riders',(string)$free,'users','violet','Can take the next trip','Riders') ?><?= U::stat('Completed trips',(string)$done,'clock','amber','Finished today','Done') ?></div>
<?= U::tabs(['/station-admin/deliveries'=>'Active trips','/station-admin/deliveries?tab=ready'=>'Ready to dispatch','/station-admin/deliveries?tab=completed'=>'Completed'],$tab==='active'?'/station-admin/deliveries':'/station-admin/deliveries?tab='.$tab) ?>
<div class="mt-5 grid gap-5 xl:grid-cols-[minmax(0,1fr)_340px]"><section class="panel p-4 md:p-5"><?= U::title($tab==='ready'?'Ready to dispatch':($tab==='completed'?'Completed trips':'Active trips'), $tab==='ready'?'check':($tab==='completed'?'clock':'truck'), 'mb-4') ?>
<?php if($tab==='ready'): ?><?= U::table(['Order','Customer','Barangay','Containers'],array_map(fn($o)=>[U::e($o[0]),U::e($o[1]),U::e($o[2]),$o[3]],$ready)) ?><?php else: $rows=[]; foreach($s['trips'] as $id=>$trip) { if(($tab==='completed')!==($trip['status']==='Completed')) continue; $load=array_sum(array_column($trip['stops'],2)); $rows[]=['<strong>Trip '.$id.'</strong>',U::e($trip['driver']),U::e($trip['area']),$load.' / '.$trip['capacity'],count($trip['stops']),U::badge($trip['status'],$trip['status']==='Completed'?'green':($trip['status']==='In progress'?'amber':'blue')),U::btn('View trip','/station-admin/trip?trip='.$id,'secondary','eye')]; } ?><?= U::table(['Trip','Driver','Area','Load','Stops','Status','Action'],$rows) ?><?php endif ?></section>
<aside class="panel h-fit scroll-mt-24 p-4 md:p-5" id="dispatch"><?= U::title('Dispatch new trip','truck','mb-4') ?><form data-local-form data-persist="station-dispatch" data-success="Trip draft saved in this browser. No rider was notified." class="space-y-4"><?= U::select('Rider','rider',['ben'=>'Ben Cruz · Available · 15 containers','mark'=>'Mark Flores · Available · 12 containers'],'ben',['required'=>true]) ?><?= U::select('Barangay','area',['Guintas'=>'Guintas'],'Guintas') ?><div class="rounded-xl bg-foam p-3.5"><p class="flex items-center gap-2 text-sm font-semibold"><?= U::icon('orders','size-4 text-water') ?>Selected ready orders</p><ul class="mt-2 space-y-1.5"><?php foreach($selected as $o): ?><li class="flex items-center justify-between gap-3 rounded-lg bg-white px-3 py-2 text-sm"><span><strong><?= U::e($o[0]) ?></strong> <span class="text-muted"><?= U::e($o[1]) ?></span></span><span class="flex items-center gap-1 whitespace-nowrap"><?= U::icon('bottle','size-4 text-water') ?><?= (int)$o[3] ?></span></li><?php endforeach; ?></ul><div class="mt-3 flex items-center justify-between border-t border-line pt-3 font-bold"><span class="flex items-center gap-2"><?= U::icon('truck','size-4 text-water') ?>Total load</span><span><?= $selectedLoad ?> / 15</span></div></div><?= U::textarea('Dispatch note','note','Handle containers carefully.',['maxlength'=>200]) ?><div class="grid gap-2"><?= U::btn('Save dispatch draft','','primary','truck',['type'=>'submit']) ?><?= U::btn('View active trip','/station-admin/trip','ghost','eye') ?></div></form></aside></div>
